  function libFor(prefix) {
    return prefix === 'outline_style' ? AXIS_LIB : LAYER_LIB;
  }

  function entriesFor(prefix) {
    const map = {};
    libFor(prefix).forEach(function (x) {
      map[x.id] = { identifier: x.id, name: x.name, content: x.text, builtin: true };
    });
    presetEntries(prefix).forEach(function (it) {
      const id = String(it.identifier);
      map[id] = { identifier: id, name: String(it.name || id), content: String(it.content || '') };
    });
    return Object.keys(map).map(function (k) { return map[k]; });
  }

  function outlineStyles() {
    const arr = presetEntries('outline_style');
    if (arr.length) {
      return arr.map(function (it) {
        return {
          id: String(it.identifier),
          name: String(it.name || it.identifier).replace(/^[^A-Za-z0-9\u4e00-\u9fa5]+/, ''),
          text: String(it.content || it.content === '' ? it.content : '').trim(),
        };
      });
    }
    return [{ id: 'builtin_gambit', name: '赌局叙事·必须付代价', text: STYLE_FALLBACK }];
  }

