  /* ------------------------------------------------------------ UI */
  let UI = {};

  function buildUi() {
    if (DOC.getElementById(ID + '-panel')) return;

    const tabBar = el('div', { id: ID + '-tabs' }, [
      el('div', { class: 'fo-tab on', 'data-tab': 'outline', text: '📜 大纲' }),
      el('div', { class: 'fo-tab', 'data-tab': 'memory', text: '🧠 记忆' }),
      el('div', { class: 'fo-tab', 'data-tab': 'settings', text: '⚙️ 设置' }),
    ]);

    const views = {
      outline: buildOutlineView(),
      memory: buildMemoryView(),
      settings: buildSettingsView(),
    };

    const panel = el('div', { id: ID + '-panel' }, [
      el('div', { class: 'fo-hd' }, [
        el('div', { class: 'fo-title' }, [
          el('span', { text: '流简 · 前端' }),
          el('span', { class: 'fo-ver', id: ID + '-ver', text: ' v' + VER }),
        ]),
        el('div', { class: 'fo-x', text: '✕', onclick: () => panel.classList.remove('open') }),
      ]),
      tabBar,
      el('div', { class: 'fo-body' }, [views.outline, views.memory, views.settings]),
    ]);

    const bubble = el('div', { id: ID + '-bubble', title: '流简前端', html: AVATAR_HTML });
    bubble.addEventListener('click', () => panel.classList.toggle('open'));

    DOC.body.appendChild(panel);
    DOC.body.appendChild(bubble);

    tabBar.addEventListener('click', (ev) => {
      const t = ev.target && ev.target.getAttribute && ev.target.getAttribute('data-tab');
      if (!t) return;
      for (const n of tabBar.children) n.classList.toggle('on', n.getAttribute('data-tab') === t);
      for (const k in views) views[k].classList.toggle('on', k === t);
    });
    views.outline.classList.add('on');
  }

  /* ------------------------------------------------------------ 通用：状态 */
  function statusSetter(id) {
    return (t) => { const n = DOC.getElementById(id); if (n) n.textContent = t; };
  }

  /* ------------------------------------------------------------ 大纲视图 */
  const SIX_DEFS = [
    { key: 'world', label: '① 世界', opts: ['现代都市', '古代／仙侠', '西幻', '科幻／末世', '自定义'], ph: '备注：一句话补世界设定（可留空）' },
    { key: 'hero', label: '② 主角', opts: ['普通人被卷入', '有秘密的强者', '反派／灰色人物', '你定'], ph: '备注：主角是谁、想要什么' },
    { key: 'tone', label: '③ 基调', opts: ['冷幽默＋算计', '黑暗压抑', '热血爽文', '你定'], ph: '备注：可以多基调组合' },
    { key: 'ending', label: '④ 结局', opts: ['赢', '输', '惨胜', '开放式'], ph: '备注：比如"能死但别死主角"' },
    { key: 'words', label: '⑥ 字数与节奏', opts: ['每节1500–2000，快', '每节2500–3500，中（默认）', '每节4000–6000，慢', '大纲流，只写关键场面'], ph: '备注：共几节、每节多少字' },
  ];

  function renderSix(host, six) {
    SIX_DEFS.forEach(function (def) {
      const sel = el('select', { id: ID + '-six-' + def.key }, def.opts.map(function (o) {
        return el('option', { value: o, text: o });
      }));
      sel.value = six[def.key] || def.opts[0];
      sel.addEventListener('change', function () { six[def.key] = sel.value; saveMem(); });
      const note = el('input', { id: ID + '-six-' + def.key + '-note', placeholder: def.ph });
      note.value = six[def.key + 'Note'] || '';
      note.addEventListener('change', function () { six[def.key + 'Note'] = note.value; saveMem(); });
      host.appendChild(el('div', {}, [el('label', { text: def.label }), sel, note]));
    });
    const scale = el('textarea', { id: ID + '-six-scale', placeholder: '⑤ 尺度：主角能不能杀人／骗人／牺牲无辜；主要角色能不能死；有没有感情线；有没有超自然' });
    scale.style.minHeight = '54px';
    scale.value = six.scale || '';
    scale.addEventListener('change', function () { six.scale = scale.value; saveMem(); });
    host.appendChild(el('div', {}, [el('label', { text: '⑤ 尺度与底线' }), scale]));
  }

  function buildOutlineView() {
    const v = el('div', { class: 'fo-view', id: ID + '-view-outline' });
    if (!M.six) M.six = {};
    const six = M.six;

    const sixHost = el('div', { id: ID + '-sixbox' });
    renderSix(sixHost, six);

    const btnResetSix = el('button', { class: 'fo-btn ghost', id: ID + '-six-reset', text: '↺ 重置六问' });
    btnResetSix.addEventListener('click', function () {
      M.six = {};
      saveMem();
      sixHost.innerHTML = '';
      renderSix(sixHost, M.six);
      setSt('六问已重置。');
    });

    const cleanName = function (x) {
      return String(x)
        .replace(/^[^A-Za-z0-9\u4e00-\u9fa5]+/, '')
        .replace(/^(大纲主轴｜|叠层｜)/, '')
        .trim();
    };
    const buildChecks = function (prefix, holderId, arrKey) {
      if (!Array.isArray(S[arrKey])) S[arrKey] = [];
      const box = el('div', { class: 'fo-checks', id: holderId });
      entriesFor(prefix).forEach(function (it) {
        const id = String(it.identifier);
        const cb = el('input', { type: 'checkbox', id: ID + '-' + prefix + '-' + id });
        cb.checked = S[arrKey].indexOf(id) >= 0;
        cb.addEventListener('change', function () {
          const i = S[arrKey].indexOf(id);
          if (cb.checked) { if (i < 0) S[arrKey].push(id); }
          else if (i >= 0) { S[arrKey].splice(i, 1); }
          saveSettings();
        });
        box.appendChild(el('label', { class: 'fo-chk', for: ID + '-' + prefix + '-' + id }, [
          cb, el('span', { text: cleanName(it.name || id) }),
        ]));
      });
      return box;
    };
    const axisBoxes = buildChecks('outline_style', ID + '-ol-axes', 'axisIds');
    const layerBoxes = buildChecks('outline_arc', ID + '-ol-layers', 'layerIds');

    const extra = el('textarea', { id: ID + '-ol-extra', placeholder: '补充设定（可选）：成长线、禁忌、想要的名场面、不想要的东西……六问没覆盖到的都写这儿' });
    extra.style.minHeight = '60px';
    extra.value = S.userIntent || '';
    extra.addEventListener('change', function () { S.userIntent = extra.value; saveSettings(); });

    const outBox = el('textarea', { id: ID + '-ol-draft', placeholder: '生成的卷纲会出现在这里，可以直接改。' });
    outBox.style.minHeight = '170px';

    const st = el('div', { class: 'fo-status', id: ID + '-st-outline', text: '' });
    const setSt = statusSetter(ID + '-st-outline');
    const badge = el('div', { class: 'fo-tip', id: ID + '-ol-badge', text: '' });

    const btnGen = el('button', { class: 'fo-btn', id: ID + '-ol-gen', text: '📜 生成卷纲' });
    const revIn = el('input', { id: ID + '-ol-rev', placeholder: '修改要求：如"第3节太赶拆成两节""主角别这么软"' });
    const btnRev = el('button', { class: 'fo-btn ghost', id: ID + '-ol-revise', text: '✏️ 按上面这条改' });
    const btnAdopt = el('button', { class: 'fo-btn ghost', id: ID + '-ol-adopt', text: '✅ 采纳并每轮注入' });
    const btnClear = el('button', { class: 'fo-btn ghost', id: ID + '-ol-clear', text: '🗑️ 扔掉当前卷纲' });

    const updateBadge = function () {
      badge.textContent = M.outline
        ? '已采纳 ' + M.outline.length + ' 字 · 每轮自动注入上下文'
        : '未采纳：现在只存在面板里，不占上下文';
    };

    const runOutline = async function (kind) {
      if (running) return;
      const prev = (outBox.value || '').trim();
      const instruction = (revIn.value || '').trim();
      if (kind === 'revise' && !prev) { setSt('先有一版草稿才能改'); return; }
      if (kind === 'revise' && !instruction) { setSt('先在输入框写修改要求'); return; }
      running = true;
      const btn = kind === 'revise' ? btnRev : btnGen;
      const oldLabel = btn.textContent;
      btn.textContent = kind === 'revise' ? '⏳ 修改中…' : '⏳ 构思中…';
      btn.disabled = true; btnRev.disabled = true; btnGen.disabled = true;
      const t0 = Date.now();
      const tick = setInterval(function () {
        setSt('⏳ ' + (kind === 'revise' ? '修改' : '构思') + '中… ' + ((Date.now() - t0) / 1000).toFixed(0) + 's');
      }, 400);
      setSt('⏳ 读取上下文…');
      try {
        S.userIntent = extra.value; saveSettings();
        const p = collectOutlineContext();
        const msgs = buildOutlineMessages(p, kind === 'revise' ? prev : '', instruction);
        const text = cleanup(await generateByAI(msgs, 'outline'));
        if (!text.trim()) throw new Error('返回为空');
        outBox.value = text;
        setSt('✅ ' + (kind === 'revise' ? '改好了' : '生成完成') + ' · ' + text.length + ' 字 · ' + ((Date.now() - t0) / 1000).toFixed(0) + 's');
        toast('✅ 卷纲已更新到面板', 'success');
      } catch (e) {
        console.error(e);
        setSt('❌ ' + (e.message || e));
        toast('卷纲生成失败：' + (e.message || e), 'error');
      } finally {
        clearInterval(tick);
        running = false;
        btn.textContent = oldLabel;
        btn.disabled = false; btnRev.disabled = false; btnGen.disabled = false;
      }
    };

    btnGen.addEventListener('click', function () { runOutline('new'); });
    btnRev.addEventListener('click', function () { runOutline('revise'); });

    btnAdopt.addEventListener('click', function () {
      const t = (outBox.value || '').trim();
      if (!t) { setSt('没有可采纳的卷纲'); return; }
      M.outline = t; saveMem(); applyMemoryInjection(); updateBadge();
      setSt('✅ 已采纳：之后每轮都会带上这段卷纲。');
      toast('✅ 已采纳，每轮注入', 'success');
    });

    btnClear.addEventListener('click', function () {
      if (!confirm('扔掉当前卷纲？之后不再每轮注入。')) return;
      M.outline = ''; saveMem(); applyMemoryInjection(); updateBadge();
      setSt('已清空卷纲。');
    });

    if (M.outline) outBox.value = M.outline;
    updateBadge();
    UI.updateOutlineBadge = updateBadge;

    v.appendChild(el('div', {}, [
      el('h4', { text: '① 六问（硬约束，缺的我按默认补，不会反问你）' }), sixHost,
      el('h4', { text: '② 大纲主轴（可多选，决定靠什么推进）' }), axisBoxes,
      el('h4', { text: '③ 叠层（可多选，决定味道）' }), layerBoxes,
      el('div', { class: 'fo-tip', text: '主轴决定"赢法"，弧光层决定"味道"，两者可以组合。以后加新主轴，在预设里加一条 outline_style_ 开头的条目即可。' }),
      el('h4', { text: '④ 补充设定（可选）' }), extra,
      el('h4', { text: '⑤ 生成' }), btnGen, st,
      el('h4', { text: '⑥ 草稿（可手改，也可让 AI 改）' }), outBox, revIn, btnRev,
      el('h4', { text: '⑦ 采用' }), badge, btnAdopt, btnClear,
      btnResetSix,
      el('div', { class: 'fo-tip', text: '采纳后走每轮注入，不再往聊天里塞楼层；扔掉后立刻从上下文移除。' }),
    ]));
    return v;
  }

  /* ------------------------------------------------------------ 设置视图 */
  function buildSettingsView() {
    const v = el('div', { class: 'fo-view', id: ID + '-view-settings' });

    const src = el('select', { id: ID + '-source' }, [
      el('option', { value: 'openai', text: 'OpenAI 兼容' }),
      el('option', { value: 'deepseek', text: 'DeepSeek（OpenAI 兼容）' }),
      el('option', { value: 'google', text: 'Google / Gemini' }),
      el('option', { value: 'claude', text: 'Claude' }),
      el('option', { value: 'custom', text: '自定义' }),
    ]);
    src.value = S.apiSource;
    const url = el('input', { id: ID + '-url', placeholder: 'https://.../v1/chat/completions' }); url.value = S.apiUrl;
    const key = el('input', { id: ID + '-key', type: 'password', placeholder: 'sk-...' }); key.value = S.apiKey;
    const model = el('input', { id: ID + '-model', placeholder: '模型名（如 DeepSeek v4.1flash）' }); model.value = S.apiModel;

    const API_PRESETS = {
      deepseek: { url: 'https://api.deepseek.com/v1', model: 'deepseek-chat' },
      google: { url: '', model: 'gemini-2.5-pro' },
      claude: { url: '', model: 'claude-sonnet-4-20250514' },
      openai: { url: '', model: '' },
      custom: { url: '', model: '' },
    };
    src.addEventListener('change', () => {
      const p = API_PRESETS[src.value] || {};
      if (p.url && !url.value.trim()) url.value = p.url;
      if (p.model && !model.value.trim()) model.value = p.model;
    });

    const n = el('input', { type: 'number', min: '0', max: '80' }); n.value = String(S.recentN);
    const words = el('input', { type: 'number', min: '300', max: '6000' }); words.value = String(S.outlineWords);

    const memN = el('input', { type: 'number', min: '0', max: '120' }); memN.value = String(S.memRecentN);
    const budget = el('input', { type: 'number', min: '200', max: '8000' }); budget.value = String(S.memBudget);
    const depth = el('input', { type: 'number', min: '0', max: '20' }); depth.value = String(S.memDepth);

    const autoDaily = el('input', { type: 'checkbox' }); autoDaily.checked = !!S.autoDaily;
    const every = el('input', { type: 'number', min: '5', max: '200' }); every.value = String(S.dailyEvery);

    const autoMem = el('input', { type: 'checkbox' }); autoMem.checked = !!S.autoInjectMem;
    const useMacro = el('input', { type: 'checkbox' }); useMacro.checked = !!S.useMacro;

    const testBtn = el('button', { class: 'fo-btn ghost', id: ID + '-api-test', text: '🔌 测试连接' });
    const stApi = el('div', { class: 'fo-status', id: ID + '-st-api', text: '' });
    let testing = false;
    testBtn.addEventListener('click', async () => {
      if (testing) return;
      testing = true; testBtn.disabled = true;
      const setStApi = statusSetter(ID + '-st-api');
      setStApi('连接中…（' + (src.value === 'deepseek' ? 'DeepSeek' : src.value) + ' / ' + (model.value.trim() || '主 API') + '）');
      const t0 = Date.now();
      try {
        sync();
        const res = await generateByAI([
          { role: 'system', content: '你是连接测试器。只回复两个字母：OK' },
          { role: 'user', content: 'ping' },
        ], 'ping', { strict: true });
        const ms = Date.now() - t0;
        const txt = String(res || '').trim().slice(0, 40);
        setStApi('✅ 连接成功 · ' + ms + 'ms · ' + (S.apiModel || '主 API') + ' → ' + (txt || '(空)'));
        toast('✅ 额外 API 连接成功', 'success');
      } catch (e) {
        const raw = String((e && e.message) || e);
        const friendly = /Cannot reconstruct tool history|no matching Tool result/i.test(raw)
          ? '当前聊天里有坏的 tool_calls 楼层（旧版遗留），ST 组装历史时崩了。删掉带 Tool calls / Error 的楼层，或新建聊天再测。'
          : raw;
        setStApi('❌ 连接失败：' + friendly);
        toast('❌ 额外 API 连接失败', 'error');
      } finally {
        testing = false; testBtn.disabled = false;
      }
    });

    const sync = () => {
      S.apiSource = src.value; S.apiUrl = url.value.trim(); S.apiKey = key.value.trim(); S.apiModel = model.value.trim();
      S.recentN = +n.value || 0; S.outlineWords = +words.value || 1200;
      S.memRecentN = +memN.value || 0; S.memBudget = +budget.value || 1200; S.memDepth = +depth.value || 4;
      S.autoDaily = autoDaily.checked; S.dailyEvery = +every.value || 20;
      S.autoInjectMem = autoMem.checked; S.useMacro = useMacro.checked;
      saveSettings(); applyMemoryInjection();
    };
    [src, url, key, model, n, words, memN, budget, depth, autoDaily, every, autoMem, useMacro]
      .forEach((x) => { x.addEventListener('change', sync); });

    v.appendChild(el('div', {}, [
      el('h4', { text: '额外 API（大纲 + 记忆共用；留空用主 API）' }),
      el('label', { text: '源' }), src,
      el('label', { text: 'URL' }), url,
      el('label', { text: 'Key' }), key,
      el('label', { text: '模型' }), model,
      testBtn, stApi,
      el('h4', { text: '大纲' }),
      el('div', { class: 'fo-row' }, [
        el('div', {}, [el('label', { text: '读最近 N 楼' }), n]),
        el('div', {}, [el('label', { text: '大纲字数' }), words]),
      ]),
      el('h4', { text: '记忆' }),
      el('div', { class: 'fo-row' }, [
        el('div', {}, [el('label', { text: '摘要读最近 N 楼' }), memN]),
        el('div', {}, [el('label', { text: '注入预算(字)' }), budget]),
      ]),
      el('label', { text: '注入深度（越小越靠后）' }), depth,
      el('label', {}, [autoDaily, ' 每满 N 楼自动生成日记']),
      el('label', { text: '自动生成的间隔楼层' }), every,
      el('label', {}, [autoMem, ' 自动注入记忆（setExtensionPrompt）']),
      el('label', {}, [useMacro, ' 同时注册宏（{{memory}} 等，预设里可用）']),
      el('div', { class: 'fo-tip', text: 'Key 存在浏览器 localStorage，公用电脑别填。' }),
    ]));
    return v;
  }

  /* ------------------------------------------------------------ 记忆视图 */
  function buildMemoryView() {
    const v = el('div', { class: 'fo-view', id: ID + '-view-memory' });
    const st = el('div', { class: 'fo-status', id: ID + '-st-mem', text: '' });
    const setSt = statusSetter(ID + '-st-mem');
    UI.memStatus = setSt;

    const treeBox = el('div', { id: ID + '-tree' });
    const sumBox = el('div', { id: ID + '-sum' });
    const preview = el('div', { class: 'fo-pre', id: ID + '-mempreview' });

    // 记忆树新增
    const tCat = el('select', {}, [
      el('option', { value: '身份', text: '身份' }),
      el('option', { value: '知识', text: '知识' }),
      el('option', { value: '关系', text: '关系' }),
      el('option', { value: '事件', text: '事件' }),
      el('option', { value: '其他', text: '其他' }),
    ]);
    const tTitle = el('input', { placeholder: '标题（例：主角真实身份）' });
    const tKeys = el('input', { placeholder: '触发词，逗号分隔（例：寒霜剑,封印）' });
    const tBody = el('textarea', { placeholder: '节点正文（要短、要事实）' });
    tBody.style.minHeight = '54px';

    const btnAdd = el('button', { class: 'fo-btn ghost', id: ID + '-tree-add', text: '＋ 添加节点' });
    btnAdd.addEventListener('click', () => {
      const title = tTitle.value.trim();
      const content = tBody.value.trim();
      if (!title || !content) { setSt('标题和正文都要填'); return; }
      M.tree.push({
        id: 'n' + Date.now().toString(36), cat: tCat.value, title: title, content: content,
        keys: tKeys.value.split(/[,，\s]+/).filter(Boolean), pin: false, on: true,
      });
      tTitle.value = ''; tKeys.value = ''; tBody.value = '';
      saveMem(); renderMemory(); setSt('已添加节点');
    });

    const btnDaily = el('button', { class: 'fo-btn', id: ID + '-mem-daily', text: '📔 生成日记（最近未归纳楼层）' });
    const btnWeekly = el('button', { class: 'fo-btn ghost', id: ID + '-mem-weekly', text: '📚 日记 → 周记' });
    const btnShiji = el('button', { class: 'fo-btn ghost', id: ID + '-mem-shiji', text: '🏛️ 周记 → 史记' });
    const btnExtract = el('button', { class: 'fo-btn ghost', id: ID + '-mem-extract', text: '🌳 从最近对话提取记忆树节点' });
    const btnRefresh = el('button', { class: 'fo-btn ghost', id: ID + '-mem-refresh', text: '↻ 刷新预览' });

    btnDaily.addEventListener('click', () => withBtn(btnDaily, '⏳ 生成日记…', () => runMemTask('daily', setSt)));
    btnWeekly.addEventListener('click', () => withBtn(btnWeekly, '⏳ 合并周记…', () => runMemTask('weekly', setSt)));
    btnShiji.addEventListener('click', () => withBtn(btnShiji, '⏳ 合并史记…', () => runMemTask('shiji', setSt)));
    btnExtract.addEventListener('click', () => withBtn(btnExtract, '⏳ 提取记忆…', () => runMemTask('extract', setSt)));
    btnRefresh.addEventListener('click', () => { applyMemoryInjection(); renderMemory(); setSt('已刷新'); });

    v.appendChild(el('div', {}, [
      el('h4', { text: '① 分层摘要' }),
      el('div', { class: 'fo-tip', text: '日记（覆盖楼层）→ 周记（合并多篇日记）→ 史记（合并多篇周记）。越往后越省 token。' }),
      btnDaily, btnWeekly, btnShiji,
      el('h4', { text: '② 记忆树' }),
      el('div', { class: 'fo-tip', text: '钉死的节点每轮都注入；其余节点只有触发词出现在最近聊天里才召回。' }),
      el('div', { class: 'fo-row' }, [
        el('div', {}, [el('label', { text: '分类' }), tCat]),
        el('div', {}, [el('label', { text: '触发词' }), tKeys]),
      ]),
      el('label', { text: '标题' }), tTitle,
      el('label', { text: '正文' }), tBody,
      btnAdd,
      btnExtract,
      treeBox,
      el('h4', { text: '③ 注入预览' }),
      btnRefresh, preview,
      st,
    ]));

    UI.treeBox = treeBox;
    UI.sumBox = sumBox;
    UI.preview = preview;
    return v;
  }

  function renderMemory() {
    if (!UI.treeBox) return;
    UI.treeBox.innerHTML = '';
    if (!M.tree.length) {
      UI.treeBox.appendChild(el('div', { class: 'fo-tip', text: '（还没有节点）' }));
    }
    for (const node of M.tree) {
      const row = el('div', { class: 'fo-item' }, [
        el('div', { class: 'fo-h' }, [
          el('span', { class: 'fo-n', text: '[' + node.cat + '] ' + node.title }),
          el('span', {}, [
            el('button', { class: 'fo-mini', text: node.pin ? '📌' : '📍', onclick: () => { node.pin = !node.pin; saveMem(); renderMemory(); } }),
            el('button', { class: 'fo-mini', text: node.on === false ? '⭕' : '✅', onclick: () => { node.on = node.on === false; saveMem(); renderMemory(); } }),
            el('button', { class: 'fo-mini', text: '✏️', onclick: () => {
              const t = prompt('标题', node.title); if (t === null) return;
              const c = prompt('正文', node.content); if (c === null) return;
              node.title = t; node.content = c; saveMem(); renderMemory();
            } }),
            el('button', { class: 'fo-mini', text: '🗑️', onclick: () => {
              if (!confirm('删除「' + node.title + '」？')) return;
              M.tree = M.tree.filter((x) => x !== node); saveMem(); renderMemory();
            } }),
          ]),
        ]),
        el('div', { class: 'fo-pre', text: node.content }),
        el('div', { class: 'fo-tip', text: '触发词：' + (node.keys.join('、') || '无') }),
      ]);
      UI.treeBox.appendChild(row);
    }

    // 摘要列表
    const host = UI.treeBox.parentElement;
    let sumHost = DOC.getElementById(ID + '-sumview');
    if (!sumHost) {
      sumHost = el('div', { id: ID + '-sumview' });
      host.insertBefore(sumHost, UI.treeBox.nextSibling);
    }
    sumHost.innerHTML = '';
    const layers = [['daily', '📔 日记'], ['weekly', '📚 周记'], ['shiji', '🏛️ 史记']];
    for (const [k, label] of layers) {
      const arr = M[k] || [];
      sumHost.appendChild(el('div', { class: 'fo-tip', text: label + '：' + arr.length + ' 条' }));
      arr.forEach((it, i) => {
        sumHost.appendChild(el('div', { class: 'fo-item' }, [
          el('div', { class: 'fo-h' }, [
            el('span', { class: 'fo-n', text: label + ' #' + (i + 1) + (it.range ? '（' + it.range[0] + '-' + it.range[1] + ' 楼）' : '') }),
            el('span', {}, [
              el('button', { class: 'fo-mini', text: '✏️', onclick: () => {
                const t = prompt('编辑', it.text); if (t === null) return;
                it.text = t; saveMem(); renderMemory();
              } }),
              el('button', { class: 'fo-mini', text: '🗑️', onclick: () => {
                if (!confirm('删除这条？')) return;
                M[k] = arr.filter((x) => x !== it); saveMem(); renderMemory();
              } }),
            ]),
          ]),
          el('div', { class: 'fo-pre', text: String(it.text || '').slice(0, 400) }),
        ]));
      });
    }
  }

  /* ------------------------------------------------------------ 大纲逻辑 */
  function currentChar() {
    const c = getCtx();
    try {
      if (!c) return { name: '', desc: '' };
      const ch = (c.characters || [])[c.thid != null ? c.thid : c.this_chid] || null;
      if (!ch) return { name: '', desc: '' };
      return {
        name: ch.name || '',
        desc: [ch.description ? '【角色描述】\n' + ch.description : '',
          ch.personality ? '【性格】\n' + ch.personality : '',
          ch.scenario ? '【场景】\n' + ch.scenario : '',
          ch.mes_example ? '【对话示例】\n' + String(ch.mes_example).slice(0, 1000) : '']
          .filter(Boolean).join('\n\n'),
      };
    } catch (e) { return { name: '', desc: '' }; }
  }

  function lastId() {
    try { return TH && TH.getLastMessageId ? TH.getLastMessageId() : -1; } catch (e) { return -1; }
  }

  function getFloors(from, to) {
    if (!TH || !TH.getChatMessages) return [];
    try {
      const a = Math.max(0, from);
      const rows = TH.getChatMessages(a + '-' + to, { hide_state: 'all', include_swipes: false }) || [];
      return rows;
    } catch (e) { return []; }
  }

  function floorText(rows, clamp) {
    return rows.map((r) => {
      const who = r.role === 'user' ? '用户' : (r.name || 'AI');
      const t = String(r.message || '')
        .replace(/<fox_outline>[\s\S]*?<\/fox_outline>/g, '')
        .replace(/<content>/g, '').replace(/<\/content>/g, '')
        .trim();
      return t ? who + '：' + t.slice(0, clamp || 1200) : '';
    }).filter(Boolean).join('\n\n');
  }

  function recentChat(n) {
    const last = lastId();
    if (last < 0) return '';
    return floorText(getFloors(last - n + 1, last)).slice(-14000);
  }

  function presetOutlineSpec() {
    try {
      if (!TH || !TH.getPreset) return '';
      const p = TH.getPreset('in_use');
      const list = (p && (p.prompts || (p.settings && p.settings.prompts))) || [];
      for (const it of list) {
        const nm = String(it && (it.name || it.identifier) || '');
        const ct = String(it && it.content || '');
        if (nm.indexOf('小说模式') >= 0 && ct.length > 200) {
          return ct.replace(/^\{\{setvar::[a-zA-Z_]+::/, '').replace(/\}\}\s*$/, '').trim();
        }
      }
    } catch (e) {}
    return '';
  }

  function collectOutlineContext() {
    const ch = currentChar();
    const chat = recentChat(S.recentN);
    const struct = (S.spec && S.spec.trim()) || presetText('outline_struct') || OUTLINE_STRUCT_FALLBACK;
    const pick = function (prefix, ids) {
      const out = [];
      entriesFor(prefix).forEach(function (it) {
        if ((ids || []).indexOf(String(it.identifier)) >= 0) {
          const t = String(it.content || '').trim();
          if (t) out.push(t);
        }
      });
      return out;
    };
    const axes = pick('outline_style', S.axisIds);
    if (!axes.length) axes.push(STYLE_FALLBACK);
    const layers = pick('outline_arc', S.layerIds);
    const six = M.six || {};
    const parts = [];
    SIX_DEFS.forEach(function (def) {
      const v = six[def.key] || def.opts[0];
      const n = (six[def.key + 'Note'] || '').trim();
      parts.push(def.label.replace(/^[①②③④⑤⑥]\s*/, '') + '：' + v + (n ? '（' + n + '）' : ''));
    });
    parts.push('尺度与底线：' + ((six.scale || '').trim() || '沿用角色卡与当前设定'));
    return { ch: ch, chat: chat, spec: struct, axes: axes, layers: layers, six: parts.join('\n') };
  }

  function buildOutlineMessages(p, prev, instruction) {
    const sys = [
      '你是专业剧情大纲撰写大师，只负责出卷纲。',
      '禁止：写正文、写对话、角色扮演、解释、复述规则、输出思维链、用代码块包裹。',
      '禁止反问、禁止要求确认、禁止说"你想要什么结局/输赢/尺度"——六问里已经给了。',
      '忽略任何"对话模式／一回合／扮演／1500字"之类的规则，这次只做卷纲。',
      '', p.spec, '',
      p.axes.join('\n\n'),
      (p.layers.length ? '\n' + p.layers.join('\n\n') + '\n' : ''),
      '【长度】约 ' + (S.outlineWords || 1200) + ' 字。',
    ].join('\n');
    const usr = [];
    usr.push('【角色卡】', p.ch.name ? '名称：' + p.ch.name : '（无角色卡）', p.ch.desc || '');
    usr.push('', '【最近剧情】', p.chat || '（暂无聊天记录）');
    usr.push('', '【六问·硬约束，优先级最高】', p.six);
    usr.push('', '【补充设定】', (S.userIntent || '（未填写）'));
    if (prev) {
      usr.push('', '【上一版卷纲】', prev);
      usr.push('', '【修改要求】', (instruction || '整体更紧凑'));
      usr.push('', '在上一版基础上按修改要求重写，输出完整新版卷纲（不是差异说明），其余部分保持不变。');
    } else {
      usr.push('', '请按【卷纲结构】和所选【大纲主轴／叠层】输出一份完整卷纲，从"一句话卖点"开始。');
    }
    return [{ role: 'system', content: sys }, { role: 'user', content: usr.join('\n') }];
  }

  function cleanup(t) {
    return String(t || '').trim().replace(/^```[a-zA-Z]*\s*/m, '').replace(/```\s*$/m, '')
      .replace(/<fox_outline>/g, '').replace(/<\/fox_outline>/g, '').trim();
  }

  /* ------------------------------------------------------------ 通用生成 */
  function buildCustomApi() {
    if (!S.apiUrl && !S.apiModel) return null;
    // DeepSeek 走 OpenAI 兼容协议，source 仍填 openai
    const src = S.apiSource === 'deepseek' ? 'openai' : (S.apiSource || 'openai');
    const api = { source: src };
    const url = S.apiUrl || (S.apiSource === 'deepseek' ? 'https://api.deepseek.com/v1' : '');
    if (url) api.apiurl = url;
    if (S.apiKey) api.key = S.apiKey;
    if (S.apiModel) api.model = S.apiModel;
    return api;
  }

  async function generateByAI(messages, tag, opts) {
    const strict = !!(opts && opts.strict);
    if (!TH || !TH.generateRaw) throw new Error('缺少 TavernHelper.generateRaw');
    const sys = messages.filter((m) => m.role === 'system').map((m) => m.content).join('\n\n');
    const usr = messages.filter((m) => m.role !== 'system').map((m) => m.content).join('\n\n');
    const req = {
      user_input: usr,
      ordered_prompts: [{ role: 'system', content: sys }, 'user_input'],
      should_silence: true, should_stream: false, max_chat_history: 1,
    };
    const custom = buildCustomApi();
    if (custom) req.custom_api = custom;
    let res;
    try { res = await TH.generateRaw(req); }
    catch (e) {
      if (custom && !strict) { delete req.custom_api; res = await TH.generateRaw(req); }
      else throw e;
    }
    return typeof res === 'string' ? res : (res && (res.content || res.text)) || '';
  }

  /* ------------------------------------------------------------ 记忆逻辑 */
  function memTextBudget() {
    const budget = S.memBudget || 1200;
    let used = 0;
    const out = [];
    if (M.outline) out.push('【本卷卷纲｜按此推进，不要复述】\n' + M.outline);
    const push = (label, text) => {
      if (!text) return;
      const room = budget - used;
      if (room <= 40) return;
      const body = String(text).slice(0, room);
      out.push(label + '\n' + body);
      used += body.length;
    };
    if (S.injectShiji) push('【史记】', (M.shiji || []).map((x) => x.text).join('\n'));
    if (S.injectWeekly) push('【周记】', (M.weekly || []).map((x) => x.text).join('\n'));
    if (S.injectDaily) push('【日记】', (M.daily || []).map((x) => x.text).join('\n'));
    if (S.injectTree) {
      const total = lastId();
      const tail = floorText(getFloors(Math.max(0, total - S.memRecentN + 1), total), 800);
      const nodes = (M.tree || []).filter((n) => n.on !== false).filter((n) => n.pin || (n.keys || []).some((k) => k && tail.indexOf(k) >= 0));
      if (nodes.length) {
        push('【记忆树】', nodes.map((n) => '·[' + n.cat + '] ' + n.title + '：' + n.content).join('\n'));
      }
    }
    if (S.injectRecent) {
      const total = lastId();
      push('【时记】', floorText(getFloors(Math.max(0, total - S.memRecentN + 1), total), 600));
    }
    return out.join('\n\n');
  }

  function applyMemoryInjection() {
    if (!M) return;
    const text = memTextBudget();
    try {
      const c = getCtx();
      if (c && c.setExtensionPrompt) {
        c.setExtensionPrompt('foxo_memory', S.autoInjectMem ? text : '', S.memPos != null ? S.memPos : 1, S.memDepth || 4, false);
      }
    } catch (e) { console.warn('[流简] setExtensionPrompt 失败', e); }
    if (UI.preview) UI.preview.textContent = text ? ('将注入 ' + text.length + ' 字：\n\n' + text.slice(0, 1200)) : '（当前没有可注入的记忆）';
  }

  function registerMacros() {
    if (!S.useMacro) return;
    try {
      const c = getCtx();
      if (!c || !c.registerMacro) return;
      const reg = (name, fn) => { try { c.registerMacro(name, fn); } catch (e) {} };
      reg('memory', () => memTextBudget());
      reg('memory_tree', () => (M.tree || []).filter((n) => n.on !== false).map((n) => '·[' + n.cat + '] ' + n.title + '：' + n.content).join('\n'));
      reg('memory_daily', () => (M.daily || []).map((x) => x.text).join('\n'));
      reg('memory_weekly', () => (M.weekly || []).map((x) => x.text).join('\n'));
      reg('memory_hourly', () => (M.shiji || []).map((x) => x.text).join('\n'));
    } catch (e) { console.warn('[流简] 注册宏失败', e); }
  }

  async function withBtn(btn, busyText, fn) {
    if (running) { toast('还有任务在跑，等它结束', 'info'); return; }
    const old = btn.textContent;
    btn.disabled = true;
    btn.textContent = busyText;
    toast(busyText, 'info');
    try { await fn(); }
    catch (e) { toast('失败：' + ((e && e.message) || e), 'error'); }
    finally { btn.disabled = false; btn.textContent = old; }
  }

  async function runMemTask(kind, setSt) {
    if (running) return;
    const total = lastId();
    if (total < 0) { setSt('没有聊天楼层'); return; }
    running = true;
    try {
      if (kind === 'extract') {
        setSt('从最近 ' + S.memRecentN + ' 楼提取记忆树…');
        const text = floorText(getFloors(Math.max(0, total - S.memRecentN + 1), total), 900);
        const res = await generateByAI([
          { role: 'system', content: '你是记忆提炼器。从对话里提取「长期有效的事实」节点，只输出 JSON 数组，不要解释。'
            + '每个元素：{"cat":"身份|知识|关系|事件|其他","title":"短标题","content":"一句话事实","keys":["触发词"]}。最多 8 个。' },
          { role: 'user', content: '对话：\n' + text + '\n\n输出 JSON 数组。' },
        ], 'extract');
        const arr = parseJsonArray(res);
        let added = 0;
        for (const it of arr) {
          if (!it || !it.title || !it.content) continue;
          if (M.tree.some((n) => n.title === it.title)) continue;
          M.tree.push({ id: 'n' + Date.now().toString(36) + added, cat: it.cat || '其他', title: it.title, content: it.content, keys: it.keys || [], pin: false, on: true });
          added += 1;
        }
        saveMem(); renderMemory(); applyMemoryInjection();
        setSt('提取完成，新增 ' + added + ' 个节点。');
        return;
      }

      if (kind === 'daily') {
        const from = Math.max(0, (M.covered || -1) + 1);
        if (from > total) { setSt('没有新的楼层可归纳'); return; }
        setSt('生成日记（' + from + '-' + total + ' 楼）…');
        const text = floorText(getFloors(from, total), 1000);
        const res = await generateByAI([
          { role: 'system', content: '你是日记撰写器。把给定楼层压成一篇 300–500 字的中文日记，保留人名、数字、承诺、伏笔、状态变化，去掉修辞。只输出日记正文。' },
          { role: 'user', content: '楼层：\n' + text },
        ], 'daily');
        M.daily.push({ text: cleanup(res), range: [from, total], ts: Date.now() });
        M.covered = total;
        saveMem(); renderMemory(); applyMemoryInjection();
        setSt('日记已生成。');
        return;
      }

      if (kind === 'weekly') {
        if ((M.daily || []).length < 2) { setSt('至少要有 2 篇日记'); return; }
        setSt('日记 → 周记…');
        const res = await generateByAI([
          { role: 'system', content: '你是周记撰写器。把多篇日记合并成一篇 400–700 字周记，合并重复、保留因果链与未解决事项。只输出正文。' },
          { role: 'user', content: M.daily.map((x, i) => '【日记' + (i + 1) + '】\n' + x.text).join('\n\n') },
        ], 'weekly');
        M.weekly.push({ text: cleanup(res), ts: Date.now() });
        M.daily = [];
        saveMem(); renderMemory(); applyMemoryInjection();
        setSt('周记已生成，日记已清空。');
        return;
      }

      if (kind === 'shiji') {
        if ((M.weekly || []).length < 2) { setSt('至少要有 2 篇周记'); return; }
        setSt('周记 → 史记…');
        const res = await generateByAI([
          { role: 'system', content: '你是史记撰写器。把多篇周记压成一篇 500–900 字编年体史记，按时间线写清人物、势力、得失、伏笔。只输出正文。' },
          { role: 'user', content: M.weekly.map((x, i) => '【周记' + (i + 1) + '】\n' + x.text).join('\n\n') },
        ], 'shiji');
        M.shiji.push({ text: cleanup(res), ts: Date.now() });
        M.weekly = [];
        saveMem(); renderMemory(); applyMemoryInjection();
        setSt('史记已生成，周记已清空。');
      }
    } catch (e) {
      console.error(e); setSt('❌ ' + (e.message || e));
    } finally { running = false; }
  }

  function parseJsonArray(t) {
    const s = String(t || '');
    const a = s.indexOf('['), b = s.lastIndexOf(']');
    if (a < 0 || b <= a) return [];
    try { const v = JSON.parse(s.slice(a, b + 1)); return Array.isArray(v) ? v : []; } catch (e) { return []; }
  }

  /* ------------------------------------------------------------ 事件 */
  function bindEvents() {
    try {
      const c = getCtx();
      if (!c || !c.eventSource || !c.eventTypes) return;
      const on = (ev, fn) => c.eventSource.on(ev, fn);
      on(c.eventTypes.CHAT_CHANGED || 'chat_id_changed', () => {
        M = loadMem(); renderMemory(); applyMemoryInjection();
      });
      on(c.eventTypes.MESSAGE_RECEIVED || 'message_received', () => {
        M.lastFloor = lastId();
        saveMem();
        if (S.autoDaily && M.lastFloor - (M.covered ?? -1) >= (S.dailyEvery || 20)) {
          runMemTask('daily', UI.memStatus || (() => {}));
        }
        applyMemoryInjection();
      });
      on(c.eventTypes.GENERATION_ENDED || 'generation_ended', () => applyMemoryInjection());
    } catch (e) { console.warn('[流简] 事件绑定失败', e); }
  }

  /* ------------------------------------------------------------ boot */
  function boot() {
    try {
      M = loadMem();
      injectCss();
      buildUi();
      renderMemory();
      applyMemoryInjection();
      registerMacros();
      bindEvents();
      console.log('[流简] 已挂载');
    } catch (e) { console.error('[流简] 挂载失败', e); }
  }

  if (DOC.readyState === 'loading') DOC.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
